// components/ThemeToggle.js
import React, { useEffect, useState } from "react";

const ThemeToggle = () => {
    const [darkMode, setDarkMode] = useState(() => {
        const stored = localStorage.getItem("blacktide-theme");
        return stored ? stored === "dark" : true;
    });

    useEffect(() => {
        const html = document.documentElement;
        if (darkMode) {
            html.classList.add("dark");
            localStorage.setItem("blacktide-theme", "dark");
        } else {
            html.classList.remove("dark");
            localStorage.setItem("blacktide-theme", "light");
        }
    }, [darkMode]);

    return (
        <div className="fixed top-4 right-4 z-50">
            <button
                onClick={() => setDarkMode((prev) => !prev)}
                className="bg-gray-800 text-white text-xs px-3 py-2 rounded shadow hover:bg-indigo-600 transition"
            >
                {darkMode ? "🌙 Dark" : "☀️ Light"}
            </button>
        </div>
    );
};

export default ThemeToggle;
