// components/SakuraHeader.js
import React from "react";
import { motion } from "framer-motion";
import { Typewriter } from "react-simple-typewriter";
import "./sakura.css"; // 添加视觉氛围样式

const SakuraHeader = () => {
    return (
        <header className="mb-16 relative">
            <motion.h1
                initial={{ opacity: 0, y: -40 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 1 }}
                className="text-5xl md:text-6xl font-bold text-pink-200 drop-shadow-lg mb-4 text-center"
            >
                ✿ Black Tide ✿
            </motion.h1>

            <motion.h2
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ delay: 0.6, duration: 1 }}
                className="text-xl md:text-2xl text-pink-100 text-center"
            >
                <Typewriter
                    words={[
                        "樱花 × 系统 × 剧情 × AI创作",
                        "Sakura × Tech × Narrative × Soul",
                        "桜とコードと世界構築",
                    ]}
                    loop={0}
                    cursor
                    cursorStyle="_"
                    typeSpeed={60}
                    deleteSpeed={40}
                    delaySpeed={1800}
                />
            </motion.h2>

            <div className="sakura-float" />
        </header>
    );
};

export default SakuraHeader;
