// components/Projects.js - 美化版，支持图片封面与卡片悬浮动效
import React from "react";
import { motion } from "framer-motion";

const projects = [
    {
        title: "🧠 AI Yandere Generator",
        desc: "Visual novel AI character generation using GPT + frontend UI",
        image: "https://images.pexels.com/photos/771742/pexels-photo-771742.jpeg", // 替换为你自己的图
    },
    {
        title: "📈 Stock Valuation Tool",
        desc: "Python + Plotly DDM/PE visualization for financial storytelling",
        image: "https://images.pexels.com/photos/3184298/pexels-photo-3184298.jpeg",
    },
    {
        title: "🌐 Portfolio Website",
        desc: "Multilingual, responsive, deployed via GitHub Pages",
        image: "https://images.pexels.com/photos/669365/pexels-photo-669365.jpeg",
    },
];

const Projects = () => {
    return (
        <motion.section
            initial={{ opacity: 0, y: 30 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 1 }}
            className="mb-12"
        >
            <h3 className="text-2xl font-semibold mb-6">Projects</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {projects.map((proj, idx) => (
                    <motion.div
                        key={idx}
                        whileHover={{ scale: 1.03 }}
                        className="bg-gray-900 rounded-lg overflow-hidden shadow-lg border border-pink-200/30 hover:border-pink-300 transition duration-300"
                    >
                        <img
                            src={proj.image}
                            alt={proj.title}
                            className="w-full h-40 object-cover"
                        />
                        <div className="p-4">
                            <h4 className="text-lg font-bold mb-1 text-pink-200">
                                {proj.title}
                            </h4>
                            <p className="text-gray-300 text-sm">{proj.desc}</p>
                        </div>
                    </motion.div>
                ))}
            </div>
        </motion.section>
    );
};

export default Projects;
