// components/BackgroundMusic.js
import React, { useEffect, useRef, useState } from "react";

const BackgroundMusic = () => {
    const audioRef = useRef(null);
    const [muted, setMuted] = useState(true);

    useEffect(() => {
        const audio = audioRef.current;
        if (audio) {
            audio.volume = 0.2;
            const playMusic = () => {
                if (!muted) audio.play().catch(() => {});
            };
            document.addEventListener("click", playMusic, { once: true });
        }
    }, [muted]);

    return (
        <div className="fixed bottom-4 right-4 z-50">
            <button
                onClick={() => setMuted((prev) => !prev)}
                className="bg-gray-800 text-white text-xs px-3 py-2 rounded shadow hover:bg-indigo-600 transition"
            >
                {muted ? "🔇 Music Off" : "🔊 Music On"}
            </button>
            <audio ref={audioRef} loop muted={muted}>
                <source
                    src="https://cdn.pixabay.com/download/audio/2022/03/15/audio_9f0473a370.mp3?filename=future-technology-ambient-112199.mp3"
                    type="audio/mpeg"
                />
            </audio>
        </div>
    );
};

export default BackgroundMusic;
